/* Runtime for code generated by tools/recomp: guest CPU state, memory access and the helpers generated code uses. */
#pragma once
#include <stdint.h>
#include <string.h>

typedef struct Cpu {
    uint32_t r[16];
    uint32_t n, z, c, v, q;     /* condition flags, one per word */
    uint32_t ctl;               /* CPSR bits 0-7: mode, T, F, I */
    uint32_t spsr;
    uint32_t bank_sp[6], bank_lr[6], bank_spsr[6];
    int64_t budget;             /* backward branches left before rc_tick */
} Cpu;

typedef void (*RcFn)(Cpu *c);
typedef struct { uint32_t addr; RcFn fn; } RcFunc;
typedef struct {
    const char *name;
    int overlay;                /* -1 for resident modules */
    uint32_t copy_src;          /* code copied from here before it runs, or 0 */
    uint32_t start, end;
    const RcFunc *funcs;
    uint32_t count;
} RcModule;
extern const RcModule rc_modules[];
extern const int rc_module_count;

/* ------------------------------------------------------------------ memory */

/* Host pointer for each 4 KB guest page, or NULL when the page is I/O or unmapped */
extern uint8_t *rc_page[1 << 20];

uint8_t rc_io_rd8(uint32_t a);
uint16_t rc_io_rd16(uint32_t a);
uint32_t rc_io_rd32(uint32_t a);
void rc_io_wr8(uint32_t a, uint8_t v);
void rc_io_wr16(uint32_t a, uint16_t v);
void rc_io_wr32(uint32_t a, uint32_t v);

static inline uint8_t rd8(uint32_t a) {
    uint8_t *p = rc_page[a >> 12];
    return p ? p[a & 0xfff] : rc_io_rd8(a);
}
static inline uint16_t rd16(uint32_t a) {
    uint8_t *p = rc_page[a >> 12];
    uint16_t v;
    if (!p) return rc_io_rd16(a & ~1u);
    memcpy(&v, p + (a & 0xffe), 2);
    return v;
}
static inline uint32_t rd32(uint32_t a) {
    uint8_t *p = rc_page[a >> 12];
    uint32_t v;
    if (!p) return rc_io_rd32(a & ~3u);
    memcpy(&v, p + (a & 0xffc), 4);
    return v;
}
/* LDR from an unaligned address rotates the aligned word */
static inline uint32_t rd32r(uint32_t a) {
    uint32_t v = rd32(a), s = (a & 3) * 8;
    return s ? (v >> s) | (v << (32 - s)) : v;
}
static inline void wr8(uint32_t a, uint8_t v) {
    uint8_t *p = rc_page[a >> 12];
    if (p) p[a & 0xfff] = v; else rc_io_wr8(a, v);
}
static inline void wr16(uint32_t a, uint16_t v) {
    uint8_t *p = rc_page[a >> 12];
    if (p) memcpy(p + (a & 0xffe), &v, 2); else rc_io_wr16(a & ~1u, v);
}
static inline void wr32(uint32_t a, uint32_t v) {
    uint8_t *p = rc_page[a >> 12];
    if (p) memcpy(p + (a & 0xffc), &v, 4); else rc_io_wr32(a & ~3u, v);
}

/* ------------------------------------------------------------------ ALU helpers */

static inline uint32_t ADD_F(Cpu *c, uint32_t a, uint32_t b, uint32_t cin) {
    uint64_t s = (uint64_t)a + b + cin;
    uint32_t res = (uint32_t)s;
    c->c = (uint32_t)(s >> 32);
    c->v = ((~(a ^ b)) & (a ^ res)) >> 31;
    c->n = res >> 31;
    c->z = res == 0;
    return res;
}

static inline uint32_t LSL_C(Cpu *c, uint32_t v, uint32_t n, uint32_t *co) {
    if (n == 0) { *co = c->c; return v; }
    if (n < 32) { *co = (v >> (32 - n)) & 1; return v << n; }
    *co = n == 32 ? v & 1 : 0;
    return 0;
}
static inline uint32_t LSR_C(Cpu *c, uint32_t v, uint32_t n, uint32_t *co) {
    if (n == 0) { *co = c->c; return v; }
    if (n < 32) { *co = (v >> (n - 1)) & 1; return v >> n; }
    *co = n == 32 ? v >> 31 : 0;
    return 0;
}
static inline uint32_t ASR_C(Cpu *c, uint32_t v, uint32_t n, uint32_t *co) {
    if (n == 0) { *co = c->c; return v; }
    if (n < 32) { *co = (v >> (n - 1)) & 1; return (uint32_t)((int32_t)v >> n); }
    *co = v >> 31;
    return (uint32_t)((int32_t)v >> 31);
}
static inline uint32_t ROR_C(Cpu *c, uint32_t v, uint32_t n, uint32_t *co) {
    if (n == 0) { *co = c->c; return v; }
    n &= 31;
    if (n == 0) { *co = v >> 31; return v; }
    *co = (v >> (n - 1)) & 1;
    return (v >> n) | (v << (32 - n));
}
static inline uint32_t RRX_C(Cpu *c, uint32_t v, uint32_t n, uint32_t *co) {
    (void)n;
    *co = v & 1;
    return (c->c << 31) | (v >> 1);
}
/* Register-specified shifts use the bottom byte of the register */
#define LSLR_C(c, v, s, co) LSL_C(c, v, (s) & 0xff, co)
#define LSRR_C(c, v, s, co) LSR_C(c, v, (s) & 0xff, co)
#define ASRR_C(c, v, s, co) ASR_C(c, v, (s) & 0xff, co)
#define RORR_C(c, v, s, co) ROR_C(c, v, (s) & 0xff, co)

static inline uint32_t QADD(Cpu *c, uint32_t a, uint32_t b) {
    int64_t s = (int64_t)(int32_t)a + (int32_t)b;
    if (s > INT32_MAX) { c->q = 1; return INT32_MAX; }
    if (s < INT32_MIN) { c->q = 1; return (uint32_t)INT32_MIN; }
    return (uint32_t)s;
}
static inline uint32_t QSUB(Cpu *c, uint32_t a, uint32_t b) {
    int64_t s = (int64_t)(int32_t)a - (int32_t)b;
    if (s > INT32_MAX) { c->q = 1; return INT32_MAX; }
    if (s < INT32_MIN) { c->q = 1; return (uint32_t)INT32_MIN; }
    return (uint32_t)s;
}
/* SMLA<x><y>/SMLAW<y>: wrapping add that sets Q on signed overflow */
static inline uint32_t QFLAG_ADD(Cpu *c, uint32_t a, uint32_t b) {
    uint32_t s = a + b;
    if ((~(a ^ b) & (a ^ s)) >> 31) c->q = 1;
    return s;
}
static inline uint32_t CLZ(uint32_t v) {
    uint32_t n = 0;
    if (!v) return 32;
    while (!(v & 0x80000000u)) { v <<= 1; n++; }
    return n;
}

/* ------------------------------------------------------------------ control flow and system */

void rc_call(Cpu *c, uint32_t addr);
void rc_tick(Cpu *c, uint32_t addr);
void rc_bad_jump(Cpu *c, uint32_t at, uint32_t target);
void rc_unimpl(Cpu *c, uint32_t at, const char *what);
void rc_trap(Cpu *c, uint32_t at);
void rc_swi(Cpu *c, uint32_t n, uint32_t at);
void rc_mcr(Cpu *c, int cp, int opc1, int crn, int crm, int opc2, uint32_t v);
uint32_t rc_mrc(Cpu *c, int cp, int opc1, int crn, int crm, int opc2);
uint32_t rc_get_cpsr(Cpu *c);
uint32_t rc_get_spsr(Cpu *c);
void rc_msr(Cpu *c, int spsr, uint32_t mask, uint32_t v);
void rc_exception_return(Cpu *c);

/* Generated code calls TICK on every backward branch, so loops reach the runtime now and then */
#define TICK(addr) do { if (--c->budget < 0) rc_tick(c, addr); } while (0)
#define RET(v) do { (void)(v); return; } while (0)
